using System.Linq;
namespace Test
{
    public class Program
    {
        public static void Main()
        {
            int? i = 1;
            short? s = 2;
            if (!new [] {i, s}.SequenceEqual(new int?[] {i, s}))
            {
                System.Console.WriteLine("Test fail at short? implicitly convert to int?");
            }
        }
    }
}
